// Frozen inputs and expected decisions generated by the pinned upstream Python
// evaluator. Replaying the corpus needs Node only; Python is not a test dependency.
import test from 'node:test';
import assert from 'node:assert/strict';
import { buildProofPack } from '../runtime/proof-pack.mjs';
import { corpus, materialize } from './proof-fixtures.mjs';

function pick(o, keys) { return Object.fromEntries(keys.map(k => [k, o[k]])); }
export function project(pack) {
  return { legacy: pick(pack.legacy, ['state', 'files']), modules: pack.modules.map(m => {
    const e = m.evidence, item = { name: m.name, track: m.track, path: m.path, verdict: m.verdict, checks: Object.fromEntries(m.checks.map(c => [c.id, c.state])), tests: pick(e.tests, ['executed', 'failed', 'skipped', 'skippedNoReason', 'stale']) };
    if (e.rules) item.rules = { ...pick(e.rules, ['tied', 'counted', 'outOfScope', 'p0NoTests', 'namedNotRun', 'perTestResults']), p0: e.rules.p0.map(r => pick(r, ['id', 'status', 'main', 'tests', 'claimed', 'by'])) };
    if (e.fresh) item.fresh = pick(e.fresh, ['cases', 'executed', 'same', 'differs', 'missing', 'selfCheck', 'reused', 'comparisons', 'inputs', 'needed']);
    if (e.baseline) item.baseline = Object.fromEntries(Object.entries(e.baseline).filter(([k]) => k.endsWith('Count') || ['renamed', 'executedDrop', 'skippedGrowth', 'targetOnly', 'ok'].includes(k)));
    if (e.baselineEvidence) item.baselineEvidence = pick(e.baselineEvidence, ['kind', 'disagree', 'conflict', 'measuredTests', 'measuredExecuted', 'measuredFailed']);
    if (e.testsChanged) item.testsChanged = pick(e.testsChanged, ['checked', 'legacyTests', 'workTests', 'counts', 'share', 'gap', 'cut']);
    if (e.deltas) item.deltas = { ...pick(e.deltas, ['parsed', 'silent', 'other', 'testFiles', 'gap']), ...Object.fromEntries(['covered', 'uncovered', 'config'].map(k => [k, e.deltas[k].map(d => d.id)])) };
    return item;
  }), toolingOnly: pack.toolingOnly, overall: pack.overall };
}
for (const spec of corpus.cases) test('upstream proof decision: ' + spec.id, async t => {
  const root = materialize(t, spec), pack = await buildProofPack(spec.system, root, spec.module, { now: spec.now ?? undefined });
  const actual = JSON.parse(JSON.stringify(project(pack))), expected = structuredClone(spec.expected);
  // os.walk's arbitrary example order differs by filesystem. The state and cap
  // are contractual; which first 20 paths happen to be listed is diagnostic.
  for (const item of [actual, expected]) item.legacy.files = item.legacy.files.length >= 20 ? { examples: item.legacy.files.length } : item.legacy.files.sort();
  // Intentional hardening: even a canary path that would otherwise be ignored
  // leaves an explicit completeness gap if it attempts to escape the workspace.
  if (spec.id.includes('.test_canary_evidence_outside_the_workspace_is_ignored:')) expected.modules[0].checks.tests = 'gap';
  assert.deepEqual(actual, expected, pack.problems.join('\n'));
});
